using NetArchTest.Rules;

public sealed class ArchitectureTests
{
    private const string DomainNamespace      = "Orders.Domain";
    private const string ApplicationNamespace = "Orders.Application";
    private const string InfraNamespace       = "Orders.Infrastructure";
    private const string WebNamespace         = "Orders.Web";

    [Fact]
    public void Domain_must_not_reference_application_or_outer_layers()
    {
        var result = Types.InAssembly(typeof(Orders.Domain.Order).Assembly)
            .Should()
            .NotHaveDependencyOnAny(
                ApplicationNamespace,
                InfraNamespace,
                WebNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful,
            "Domain layer has forbidden outward dependency:\n" +
            string.Join("\n", result.FailingTypeNames ?? []));
    }

    [Fact]
    public void Application_must_not_reference_infrastructure_or_web()
    {
        var result = Types.InAssembly(typeof(Orders.Application.PlaceOrderCommand).Assembly)
            .Should()
            .NotHaveDependencyOnAny(InfraNamespace, WebNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful,
            "Application layer has forbidden outward dependency:\n" +
            string.Join("\n", result.FailingTypeNames ?? []));
    }

    [Fact]
    public void Repositories_must_implement_IRepository_and_live_in_infrastructure()
    {
        var result = Types.InCurrentDomain()
            .That().ImplementInterface(typeof(IRepository<>))
            .Should()
            .ResideInNamespace(InfraNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful,
            "Repository implementation found outside Infrastructure:\n" +
            string.Join("\n", result.FailingTypeNames ?? []));
    }
}

