{
    try
    {
        var body = args.Data.Body.ToArray();
        var orderEvent = JsonSerializer.Deserialize<OrderPlaced>(body);

        if (orderEvent is not null)
        {
            logger.LogInformation(
                "Processing order {OrderId} from partition {Partition}",
                orderEvent.OrderId,
                args.Partition.PartitionId);

            await orderService.ProcessAsync(orderEvent, args.CancellationToken);
        }

        // Simple example: checkpoint after success. At scale, checkpoint less often.
        await args.UpdateCheckpointAsync(args.CancellationToken);
    }
    catch (Exception ex)
    {
        logger.LogError(ex,
            "Failed to process event from partition {Partition}",
            args.Partition.PartitionId);
        // Do NOT checkpoint on failure — event will be reprocessed
    }
};

processor.ProcessErrorAsync += args =>
{
    logger.LogError(args.Exception,
        "Event Hubs processor error on partition {Partition}",
        args.PartitionId);
    return Task.CompletedTask;
};

await processor.StartProcessingAsync();
await Task.Delay(Timeout.Infinite); // Keep alive
