app.MapPost("/webhooks/payments", async (
    HttpRequest request,
    AppDbContext db,
    IConfiguration config,
    CancellationToken ct) =>
{
    // Read raw body before any model binding
    using var reader = new StreamReader(request.Body);
    var rawBody = await reader.ReadToEndAsync(ct);

    // Verify HMAC-SHA256 signature
    var signature = request.Headers["X-Signature-256"].ToString();
    var secret = config["Webhooks:PaymentSecret"]!;

    if (!IsValidSignature(rawBody, signature, secret))
        return Results.Unauthorized();

    // Idempotency: reject already-processed events
    var eventId = request.Headers["X-Event-Id"].ToString();
    if (await db.ProcessedWebhooks.AnyAsync(w => w.EventId == eventId, ct))
        return Results.Ok(); // Already handled

    // Durable handoff — write to outbox before responding
    db.WebhookInbox.Add(new WebhookInboxEntry(
        EventId: eventId,
        Source: "payments",
        Payload: rawBody,
        ReceivedAt: DateTime.UtcNow));

    await db.SaveChangesAsync(ct);
    return Results.Ok();
});

static bool IsValidSignature(string body, string signature, string secret)
{
    var key = Encoding.UTF8.GetBytes(secret);
    var hash = HMACSHA256.HashData(key, Encoding.UTF8.GetBytes(body));
    var expected = $"sha256={Convert.ToHexString(hash).ToLowerInvariant()}";
    return CryptographicOperations.FixedTimeEquals(
        Encoding.UTF8.GetBytes(expected),
        Encoding.UTF8.GetBytes(signature));
}

public sealed record WebhookInboxEntry(
    string EventId, string Source,
    string Payload, DateTime ReceivedAt);

