// Custom check: verifies a business-critical queue is reachable
public sealed class MessageBusHealthCheck(
    IServiceBusClientFactory factory) : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken ct)
    {
        try
        {
            var client = factory.CreateAdminClient();
            var props = await client.GetQueueRuntimePropertiesAsync(
                "order-events", ct);

            var data = new Dictionary<string, object>
            {
                ["activeMessages"] = props.Value.ActiveMessageCount,
                ["deadLetterMessages"] = props.Value.DeadLetterMessageCount
            };

            return props.Value.DeadLetterMessageCount > 1000
                ? HealthCheckResult.Degraded("High dead-letter count", data: data)
                : HealthCheckResult.Healthy(data: data);
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy(
                "Service Bus unreachable", ex);
        }
    }
}

