public sealed class Order
{
    public Guid Id { get; private set; }
    public OrderStatus Status { get; private set; }
    public decimal Total { get; private set; }

    public static (Order, IReadOnlyList<object>) Place(
        Guid id, CustomerId customerId, IEnumerable<OrderLine> lines)
    {
        var order = new Order();
        var events = new List<object>
        {
            new OrderPlaced(id, customerId, lines.ToList(), DateTime.UtcNow)
        };
        foreach (var e in events) order.Apply(e);
        return (order, events);
    }

    public (IReadOnlyList<object> Events) Cancel(string reason)
    {
        if (Status != OrderStatus.Pending)
            throw new DomainException("Only pending orders can be cancelled.");

        var events = new List<object> { new OrderCancelled(Id, reason, DateTime.UtcNow) };
        foreach (var e in events) Apply(e);
        return (events);
    }

    private void Apply(object @event)
    {
        switch (@event)
        {
            case OrderPlaced e:
                Id = e.OrderId;
                Status = OrderStatus.Pending;
                Total = e.Lines.Sum(l => l.Subtotal);
                break;
            case OrderCancelled:
                Status = OrderStatus.Cancelled;
                break;
        }
    }

    // Reconstitution: load from event stream
    public static Order Rehydrate(IEnumerable<object> events)
    {
        var order = new Order();
        foreach (var e in events) order.Apply(e);
        return order;
    }
}

public sealed record OrderPlaced(
    Guid OrderId, CustomerId CustomerId,
    IReadOnlyList<OrderLine> Lines, DateTime OccurredAt);

public sealed record OrderCancelled(
    Guid OrderId, string Reason, DateTime OccurredAt);

