public sealed class ProductCache(
    IDistributedCache cache,
    IProductRepository repository)
{
    private static readonly DistributedCacheEntryOptions DefaultOptions = new()
    {
        AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5),
        SlidingExpiration = TimeSpan.FromMinutes(2)
    };

    public async Task<ProductDto?> GetAsync(
        Guid productId, CancellationToken ct)
    {
        var key = $"product:{productId}";

        var cached = await cache.GetStringAsync(key, ct);
        if (cached is not null)
            return JsonSerializer.Deserialize<ProductDto>(cached);

        var product = await repository.FindAsync(productId, ct);
        if (product is null) return null;

        await cache.SetStringAsync(
            key,
            JsonSerializer.Serialize(product),
            DefaultOptions,
            ct);

        return product;
    }

    public Task InvalidateAsync(Guid productId, CancellationToken ct) =>
        cache.RemoveAsync($"product:{productId}", ct);
}

